CREATE OR REPLACE FUNCTION public.ca_can_oversee_union(p_union_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR p_union_id IS NULL THEN RETURN false; END IF;
  IF fn_is_union_overseer(p_union_id, v_uid) THEN RETURN true; END IF;
  RETURN EXISTS (SELECT 1 FROM profiles p
                  WHERE p.id = v_uid AND COALESCE(p.is_admin, false));
END;
$function$

CREATE OR REPLACE FUNCTION public.ca_union_record_presettlement(p_union_id uuid, p_club_id uuid, p_amount numeric, p_method text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_res jsonb;
  v_total numeric;
BEGIN
  IF NOT ca_can_oversee_union(p_union_id) THEN
    RAISE EXCEPTION 'not authorized for this union' USING ERRCODE = '42501';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'enter an amount greater than zero');
  END IF;

  -- The underlying function does its own membership and authorization checks
  -- and returns a jsonb result rather than raising; pass it straight through.
  v_res := fn_union_record_presettlement(p_union_id, p_club_id, p_amount,
                                         p_method, p_reference, p_note);
  IF NOT COALESCE((v_res->>'success')::boolean, false) THEN
    RETURN v_res;
  END IF;

  -- What this club has been credited that is not yet tied to a statement -
  -- i.e. what the next square-up will subtract.
  SELECT COALESCE(SUM(amount), 0) INTO v_total
    FROM union_presettlements
   WHERE union_id = p_union_id AND club_id = p_club_id
     AND applied_settlement_id IS NULL;

  RETURN v_res || jsonb_build_object('unapplied_total', round(v_total, 2));
END;
$function$
